fixture item=WorkBatch {items=[WorkItem {title="T"}]}
derive make():WorkItem=WorkItem {title="T"}
scenario make_one() by=members -> WorkItem
 do return WorkItem {title="T"}

Item {
 # A name. @{nl="Naam."}
 name:text trim,
 ## Never a metadata string
 #= descriptions.state
 state:enum(on,off)=on label={text="State"@{"pt-BR"="Estado",nl=null},values={on="On",off="Off"}}
}
# Quoted \@{literal} marker.
message hello(name:text)="Hello {name}"@{nl="Hallo {name}"}

derive a(name:text):Item=Item {
 name,
 title=name
}
derive b(name:text):Item=Item {name,title=name}
derive c(name:text):Item=Item {
 true=name,
 false=name
}

scenario make() by=members -> json
 do
  return {value=1}
scenario update(item:Item) by=members
 do
  set item {value=1}
  call (pkg.run) {item}
  send (Remote.run) {item} as delivery

derive names():json = [
 Given,
 When,
 Then
]
Item {
 Given:text,
 When:text,
 Then:text
}

event {from:date,until:date}
contract {data:json}
context {theme:text}
preferences {view:enum(one,two)=one}
role {active:bool}
message {caption:text}
Then {Given:When}
